    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the object centers: each object is a diamond/plus-like quartet.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))
    # If two centers are separated horizontally, bridge their inner tips
    # on the row between their vertical arms.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            if r1 == r2:
                for c in range(c1 + 2, c2 - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            # Same logic vertically, using the column shared by the pair.
            if c1 == c2:
                for r in range(r1 + 2, r2 - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    # Fill intervals between aligned diagonal pairs with adjacent centers
    # whose distance is 6, matching the two visible horizontal groups.
    for r in range(h):
        cols = [c for c in range(1, w - 1)
                if grid[r][c - 1] == 2 and grid[r][c + 1] == 2]
        for c in cols:
            for d in cols:
                if d - c == 6:
                    for x in range(c + 3, d - 1):
                        if out[r][x] == 0:
                            out[r][x] = 1
    return out
